import{_ as l,a0 as p,w as o,s as d,ao as c,I as n,x as s,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9","title":"如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM","tag":"202305","desc":""},"relativePath":"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9.md","filePath":"[post].md"}'),h={name:"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9.md"};function r(g,i,u,k,b,m){const a=p("Link");return o(),d("div",null,[i[15]||(i[15]=c(`<h1 id="如何在-rocky-linux-9-almalinux-9-上安裝-kvm" tabindex="-1">如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM <a class="header-anchor" href="#如何在-rocky-linux-9-almalinux-9-上安裝-kvm" aria-label="Permalink to “如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/25/155857v1e939ckoj3eaxe3.jpg" alt=""></p><blockquote><p>在本指南中，我們演示瞭如何在 Rocky Linux 9 / Alma Linux 9 上安裝 KVM。</p></blockquote><p>KVM 是 <ruby>內核虛擬機<rt>Kernel Virtualization Machine</rt></ruby> 的簡稱，是一個為 Linux 內核設計的開源虛擬化平台。它是一種 1 類管理程序，或通常稱為裸機管理程序。它允許用户創建和管理多台客户機，這些可以在 Linux 或 Windows 操作系統中創建。</p><p>與大多數虛擬化平台一樣，它將硬件資源（如 CPU、內存、存儲、網絡、圖形等）抽象化，並將它們分配給獨立於宿主機運行的客户機。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><ul><li>預裝 Rocky Linux 9 / AlmaLinux 9</li><li>具有管理員權限的 sudo 用户</li><li>互聯網連接</li></ul><h3 id="_1、驗證是否啓用了硬件虛擬化" tabindex="-1">1、驗證是否啓用了硬件虛擬化 <a class="header-anchor" href="#_1、驗證是否啓用了硬件虛擬化" aria-label="Permalink to “1、驗證是否啓用了硬件虛擬化”">​</a></h3><p>首先，你需要驗證你的系統是否啓用了虛擬化功能。在大多數現代系統上，此功能已在 BIOS 中啓用。但可以肯定的是，你可以驗證是否如圖所示啓用了虛擬化。</p><p>該命令探測是否存在 VMX（<ruby>虛擬機擴展<rt>Virtual Machine Extension</rt></ruby>），它是英特爾硬件虛擬化的 CPU 標誌，或 SVM，它是 AMD 硬件虛擬化的標誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/cpuinfo | egrep &quot;vmx|svm&quot;</span></span></code></pre></div><p>從以下輸出中，你可以看到我們的系統啓用了英特爾硬件虛擬化：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Intel-VT-Check-CPU-Flags-Grep-Command.png" alt=""></p><h3 id="_2、在-rocky-linux-9-almalinux-9-上安裝-kvm" tabindex="-1">2、在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM <a class="header-anchor" href="#_2、在-rocky-linux-9-almalinux-9-上安裝-kvm" aria-label="Permalink to “2、在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM”">​</a></h3><p>確保啓用虛擬化後，下一步就是安裝 KVM 和管理工具。為此，請運行以下 <code>dnf</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install qemu-kvm virt-manager libvirt virt-install virt-viewer virt-top bridge-utils  bridge-utils virt-top libguestfs-tools -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/dnf-install-lvm-qemu-rocky-almalinux9.png" alt=""></p><p>安裝完成後，運行以下命令檢查是否已加載所需的 KVM 模組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | grep kvm</span></span></code></pre></div><p>你應該得到以下輸出以確認已加載必要的模組：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/List-KVM-Module-lsmod-command.png" alt=""></p><h3 id="_3、啓動並啓用-libvirtd-守護進程" tabindex="-1">3、啓動並啓用 libvirtd 守護進程 <a class="header-anchor" href="#_3、啓動並啓用-libvirtd-守護進程" aria-label="Permalink to “3、啓動並啓用 libvirtd 守護進程”">​</a></h3><p>在下一步中，一定要啓動 libvirtd 守護進程。這是一個服務器端守護程序組件，可在虛擬化的客户機上運行和管理任務。它用於管理虛擬化技術，例如 Xen、KVM 和 ESXi 等等。</p><p>要啓動 libvirtd 守護進程，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start libvirtd</span></span></code></pre></div><p>請務必啓用該服務以在引導時啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now libvirtd</span></span></code></pre></div><p>驗證 libvirtd 守護進程是否正在運行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status libvirtd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Libvirtd-Service-Status-RockyLinux-AlmaLinux.png" alt=""></p><h3 id="_4、設置橋接接口" tabindex="-1">4、設置橋接接口 <a class="header-anchor" href="#_4、設置橋接接口" aria-label="Permalink to “4、設置橋接接口”">​</a></h3><p>到目前為止，我們已經安裝了 KVM 和所有管理工具，事實上，我們可以繼續啓動虛擬機。但是，如果我們可以從管理程序網絡外部訪問虛擬機，那就太好了。為此，我們需要創建一個橋接接口。</p><p>首先，確定系統上的網絡接口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection show</span></span></code></pre></div><p>從輸出來看，<code>ens160</code> 是活動的網絡接口，請務必注意你的情況下的接口，因為你將一路使用它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-show-output-rockylinux9.png" alt=""></p><p>要開始創建網橋，首先，使用以下語法用其 UUID 刪除連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection delete UUID</span></span></code></pre></div><p>在我們的例子中，命令將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection delete 19e98123-9a84-30a6-bc59-a7134446bb26</span></span></code></pre></div><p>你將收到連接已成功刪除的確認信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-delete-output.png" alt=""></p><p>在繼續進行之前，最好準備好以下詳細信息：</p><ul><li>網橋名稱 – 新網橋的首選名稱（例如 <code>br1</code>）</li><li>設備名稱 – 這是你的網絡接口的名稱。它將作為網橋的從屬設備（例如，<code>ens160</code>）</li><li>IP 地址/子網 – 橋接網絡的 IP 地址和子網（例如 <code>192.168.2.50/24</code>）。請注意，這應該與你的網絡子網和 IP 地址相對應。</li><li>網關 – 你網絡的默認網關地址（例如 <code>192.168.2.1</code>）</li><li>DNS1 和 DNS2 – 首選 DNS 地址（例如 <code>8.8.8.8</code> 和 <code>8.8.4.4</code>）</li></ul><p>繼續，使用以下語法創建一個新的橋接接口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge autoconnect yes con-name BRIDGE NAME ifname BRIDGE NAME</span></span></code></pre></div><p>在我們的例子中，<code>br1</code> 是首選的網橋接口名稱。因此，命令將如圖所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge autoconnect yes con-name br1 ifname br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/create-Bridge-nmcli-rockylinux-almalinux.png" alt=""></p><p>在接下來的步驟中，你將通過指定 IP 子網、網關和 DNS 值來修改網橋。</p><p>首先使用以下語法指定 IP 子網：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.addresses IP ADDRESS/SUBNET ipv4.method manual</span></span></code></pre></div><p>根據我們的設置，命令將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.addresses 192.168.2.150/24 ipv4.method manual</span></span></code></pre></div><p>接下來，使用以下語法指定網關地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.gateway GATEWAY</span></span></code></pre></div><p>根據我們的網絡，該命令採用以下格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.gateway 192.168.2.1</span></span></code></pre></div><p>DNS 地址的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.dns DNS1 +ipv4.dns DNS2</span></span></code></pre></div><p>該命令採用以下格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.dns 8.8.8.8 +ipv4.dns 8.8.4.4</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Add-IP-Gateway-DNS-Network-Bridge-RockyLinux-AlmaLinux.png" alt=""></p><p>此後，使用以下命令添加網橋從屬設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge-slave autoconnect yes con-name DEVICE NAME ifname DEVICE NAME master BRIDGE NAME</span></span></code></pre></div><p>使用我們的值，命令如圖所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge-slave autoconnect yes con-name ens160 ifname ens160 master br1</span></span></code></pre></div><p>你將收到以下確認信息，表明已成功添加網橋從屬設備。請記住，橋接從屬設備是你的網絡接口或適配器。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Network-Bridge-AutoConnect-Nmcli-RockyLinux-AlmaLinux.png" alt=""></p><p>要確認網橋已創建，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection show</span></span></code></pre></div><p>從輸出中，你可以看到列出了網橋接口。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-show-after-bridge-creation.png" alt=""></p><p>激要活它，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection up br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Network-Bridge-Up-Command-RockyLinux-AlmaLinux.png" alt=""></p><p>此外，你可以使用 <code>ip addr</code> 命令驗證：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr | grep br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Check-Bridge-Ip-address-RockyLinux-AlmaLinux.png" alt=""></p><p>最後，編輯網橋配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/qemu-kvm/bridge.conf</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow all</span></span></code></pre></div><p>然後重新啓動虛擬化守護進程以應用更改</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart libvirtd</span></span></code></pre></div><h3 id="_5、創建虛擬機" tabindex="-1">5、創建虛擬機 <a class="header-anchor" href="#_5、創建虛擬機" aria-label="Permalink to “5、創建虛擬機”">​</a></h3><p>安裝 KVM 並配置橋接連接後，現在讓我們創建一個虛擬機。在執行之前，為登錄用户分配必要的所有權，以便在不切換到 root 的情況下運行命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chown -R $USER:libvirt /var/lib/libvirt/</span></span></code></pre></div><p>在命令列上，我們將使用以下語法使用 Ubuntu 20.04 ISO 鏡像創建虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ virt-install \\</span></span>
<span class="line"><span>    --name Ubuntu \\</span></span>
<span class="line"><span>    --ram 2048 \\</span></span>
<span class="line"><span>    --vcpus 2 \\</span></span>
<span class="line"><span>    --disk path=/var/lib/libvirt/images/ubuntu-20.04.img,size=15 \\</span></span>
<span class="line"><span>    --os-variant ubuntu20.04 \\</span></span>
<span class="line"><span>    --network bridge=br1,model=virtio \\</span></span>
<span class="line"><span>    --graphics vnc,listen=0.0.0.0 \\</span></span>
<span class="line"><span>    --console pty,target_type=serial \\</span></span>
<span class="line"><span>    --cdrom /home/linuxtechi/Downloads/ubuntu-20.04.4-desktop-amd64.iso</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Virt-Install-command-RockyLinux-AlmaLinux.png" alt=""></p><p>執行該命令後，將啓動圖形屏幕會話，並開始安裝客户操作系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/VNC-connection-KVM-VM-RockyLinux-AlmaLinux.png" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/VNC-Console-KVM-GUI-RockyLinux-AlmaLinux.png" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們關於如何在 Rocky Linux 9 / AlmaLinux 9 上安裝 KVM 的文章到此結束，非常歡迎你提供反饋。</p><p><em>（題圖：MJ/a364d6e3-0c59-4be8-bf02-5df078359429）</em></p><hr>`,98)),n("p",null,[i[1]||(i[1]=s("via: ",-1)),e(a,{href:"https://www.linuxtechi.com/install-kvm-on-rocky-linux-almalinux/"},{default:t(()=>[...i[0]||(i[0]=[s("https://www.linuxtechi.com/install-kvm-on-rocky-linux-almalinux/",-1)])]),_:1})]),n("p",null,[i[6]||(i[6]=s("作者：",-1)),e(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...i[2]||(i[2]=[s("Pradeep Kumar",-1)])]),_:1}),i[7]||(i[7]=s(" 選題：",-1)),e(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...i[3]||(i[3]=[s("lkxed",-1)])]),_:1}),i[8]||(i[8]=s(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...i[4]||(i[4]=[s("geekpi",-1)])]),_:1}),i[9]||(i[9]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...i[5]||(i[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[12]||(i[12]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[10]||(i[10]=[s("LCTT",-1)])]),_:1}),i[13]||(i[13]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...i[11]||(i[11]=[s("Linux中國",-1)])]),_:1}),i[14]||(i[14]=s(" 榮譽推出",-1))])])}const v=l(h,[["render",r]]);export{f as __pageData,v as default};
